<script setup lang="ts">
import { ref, onMounted, onUnmounted } from 'vue';
import { api, json } from './api';
interface Run { run_id:string; task:string; status:string; plan:string; diff:string; reason:string; calls:number; repairs:number; workspace:string; verification: {status?:string;summary?:string;data?:{output?:string;exit_code?:number}}; usage:Record<string,number> }
interface RunEvent {seq:number;event:string;data:Record<string,unknown>}
const runs = ref<Run[]>([]), current = ref<Run | null>(null), events = ref<RunEvent[]>([]);
const repository = ref(''), task = ref('修复 Python 函数的边界条件，并补充回归测试。'), mode = ref('demo'), error=ref(''), busy=ref(false), tab=ref('timeline');
let source: EventSource | null = null, poll: ReturnType<typeof setInterval>;
const labels:Record<string,string>={created:'已创建',running:'执行中',awaiting_approval:'计划待确认',interrupted:'已暂停',succeeded:'测试已通过',failed:'执行失败',blocked:'验证受阻',demo_complete:'演示完成'};
async function refresh() { runs.value=await api<Run[]>('/api/runs'); if(current.value) current.value=runs.value.find(r=>r.run_id===current.value?.run_id)||current.value; }
async function useDemo() { try { repository.value=(await api<{repository:string}>('/api/demo-repository',{method:'POST'})).repository; task.value='修复 calculator.py 的 add 函数，使回归测试通过。'; } catch(e) { error.value=String(e); } }
async function select(run:Run) {
  current.value=run; events.value=[]; source?.close();
  source = new EventSource(`/api/runs/${run.run_id}/events`);
  source.onmessage = event => { const item = JSON.parse(event.data) as RunEvent; if (!events.value.some(e=>e.seq===item.seq)) events.value.push(item); void refresh().catch(()=>{}); };
  source.onerror = () => source?.close();
}
async function create() { busy.value=true; error.value=''; try { const run=await api<Run>('/api/runs',json({repository:repository.value,task:task.value})); await refresh(); await select(run); } catch(e){error.value=String(e);} finally{busy.value=false;} }
async function action(name:string) { if(!current.value)return; error.value=''; try { await api(`/api/runs/${current.value.run_id}/${name}`,{method:'POST'}); await refresh(); await select(current.value); }catch(e){error.value=String(e);} }
onMounted(async()=>{try{mode.value=(await api<{mode:string}>('/api/health')).mode;await refresh();if(runs.value[0])await select(runs.value[0]); poll=setInterval(()=>void refresh().catch(()=>{}),2000);}catch(e){error.value=String(e);}});
onUnmounted(()=>{source?.close();clearInterval(poll);});
</script>

<template>
  <div class="shell forge">
    <aside class="sidebar"><div class="brand"><div class="mark">⌁</div>forge<span style="font-size:11px;color:#8eaa9c"> / lite</span></div><div><div class="eyebrow" style="margin-bottom:14px">ENGINEERING WORKSPACE</div><nav class="nav"><button class="active">⌘ &nbsp; 编码任务</button></nav></div><div><div class="eyebrow" style="margin-bottom:14px">RECENT RUNS</div><nav class="nav"><button v-for="run in runs.slice(0,8)" :key="run.run_id" @click="select(run)" :class="{active:current?.run_id===run.run_id}"><span style="display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:170px">{{run.task}}</span><small style="display:block;margin-top:5px;opacity:.65">{{labels[run.status]}}</small></button></nav></div><div class="side-note"><strong>Build. Verify. Inspect.</strong><br>改动留在独立 worktree。每次工具调用与验证结果，都有迹可循。</div></aside>
    <main class="main"><header class="topbar"><span>工作空间 &nbsp; / &nbsp; 编码任务</span><span class="badge"><span class="dot"></span>{{mode==='demo'?'DEMO · 只读流程演示':'LIVE · 工具调用模式'}}</span></header><section class="hero"><div><div class="eyebrow" style="margin-bottom:13px">SMALL AGENT. VISIBLE WORK.</div><h1>把一个任务，<br>变成可审查的改动。</h1><p>从计划到补丁，从测试到证据。<br>一个精简的编码 Agent，让执行过程清晰可见。</p></div><div class="hero-art">⌘</div></section>
      <div class="stats"><div class="stat"><span>任务运行 / RUNS</span><strong>{{String(runs.length).padStart(2,'0')}}</strong></div><div class="stat"><span>模型调用 / CURRENT RUN</span><strong>{{current?.calls||0}} <small class="muted">calls</small></strong></div><div class="stat"><span>验证结果 / CURRENT RUN</span><strong style="font-size:18px">{{current?.verification?.status==='succeeded'?'测试通过':current?.verification?.status==='failed'?'测试失败':'尚未验证'}}</strong></div></div>
      <div v-if="error" class="error" role="alert">{{error}}</div><div class="grid">
        <section><div class="card"><div class="card-header"><h2>启动一个工程任务</h2><span class="muted">01 — DEFINE</span></div><button class="secondary tiny" @click="useDemo">使用示例仓库</button><label class="field" for="repo">本地 Git 仓库 · 基于当前 HEAD 创建隔离 worktree</label><input id="repo" v-model="repository" class="wide" placeholder="C:\projects\my-python-app"><label class="field" for="task">任务描述</label><textarea id="task" v-model="task" rows="3"></textarea><div class="row" style="justify-content:space-between;margin-top:15px"><span class="muted">先生成计划，再开始执行</span><button @click="create" :disabled="busy||!repository.trim()||!task.trim()">{{busy?'正在准备…':'生成执行计划 ↗'}}</button></div></div>
        <div v-if="current" class="card"><div class="card-header"><h2>执行工作台</h2><span class="badge">{{labels[current.status]||current.status}}</span></div><div class="muted" style="margin-bottom:15px">RUN {{current.run_id.slice(0,8)}} · {{current.reason||'等待下一步'}}</div><div v-if="current.plan" class="answer-block" style="margin:0 0 18px"><div class="eyebrow" style="margin-bottom:12px">IMPLEMENTATION PLAN</div><div class="answer">{{current.plan}}</div></div><div class="row" style="margin-bottom:20px"><button v-if="current.status==='awaiting_approval'" @click="action('start')">确认计划并执行 →</button><button v-if="current.status==='running'" class="secondary" @click="action('cancel')">暂停执行</button><button v-if="current.status==='interrupted'" @click="action('resume')">恢复任务 →</button></div><div class="tabs"><button :class="{active:tab==='timeline'}" @click="tab='timeline'">执行轨迹</button><button :class="{active:tab==='diff'}" @click="tab='diff'">代码 Diff</button><button :class="{active:tab==='tests'}" @click="tab='tests'">验证证据</button></div><div v-if="tab==='timeline'" class="timeline"><div class="event" v-for="event in events" :key="event.seq"><strong>{{event.event.toUpperCase()}}</strong><pre>{{JSON.stringify(event.data,null,2)}}</pre></div><div v-if="!events.length" class="empty">执行事件将在这里实时显示。</div></div><div v-if="tab==='diff'"><pre v-if="current.diff" class="diff">{{current.diff}}</pre><p v-else class="empty">暂无代码改动。演示模式只读取仓库。</p></div><div v-if="tab==='tests'"><pre v-if="current.verification?.status">{{JSON.stringify(current.verification,null,2)}}</pre><p v-else class="empty">尚无测试执行证据。<br>演示模式不会执行或模拟通过测试。</p></div></div></section>
        <section><div class="card"><div class="card-header"><h2>一个透明的执行循环</h2><span class="muted">02 — EXECUTE</span></div><div class="flow"><div><b>01</b><span>理解与规划<small>先确认任务范围与验证方式</small></span></div><div><b>02</b><span>工具调用<small>读取 · 搜索 · 校验后写入</small></span></div><div><b>03</b><span>隔离验证<small>禁网 Docker 中运行 pytest</small></span></div><div><b>04</b><span>交付证据<small>Diff · 退出码 · 调用记录</small></span></div></div></div><div class="card"><div class="eyebrow" style="margin-bottom:15px">BUILT WITH BOUNDARIES</div><p style="font-size:13px;color:#698171">源仓库的未提交改动不会进入任务。Agent 不执行主机任意命令，也不自动提交或推送。</p><p class="muted" style="margin-bottom:0">Docker 不可用、测试未通过或调用预算耗尽，都将保留明确状态。</p></div><div v-if="current" class="card"><div class="eyebrow" style="margin-bottom:15px">RUN ARTIFACTS</div><p class="muted">worktrees / {{current.run_id.slice(0,8)}}</p><details><summary class="muted">查看本地完整路径</summary><p class="muted" style="overflow-wrap:anywhere">{{current.workspace}}</p></details><pre>{{JSON.stringify(current.usage,null,2)}}</pre></div></section>
      </div><footer class="footer">FORGE AGENT LITE &nbsp; / &nbsp; PLAN → ACT → VERIFY → INSPECT</footer>
    </main>
  </div>
</template>

<style>
.forge .mark,.forge button:not(.secondary):not(.tiny):not(.nav button):not(.tabs button){background:#264b43}.forge .hero-art{background:linear-gradient(145deg,#e7edde,#ebdfc6);color:#806b3d}.forge .sidebar{background:#f1f4ef}.forge .main{background:#faf9f5}.forge .hero .eyebrow{color:#9e8856}.flow>div{display:flex;gap:18px;padding:19px 0;border-bottom:1px solid #edf0e8}.flow>div:last-child{border:0}.flow b{color:#a99a77;font:20px 'Manrope'}.flow span{font-weight:600;font-size:13px}.flow small{display:block;font-weight:400;color:#87958a;margin-top:7px;font-size:12px}.diff{background:#17352e;color:#c6e4c7;padding:20px;border-radius:10px}.forge .event pre{max-height:250px}
</style>
